            return ResponseEntity.status(HttpStatus.CREATED).body(response);
        } catch (Exception e) {
            logger.error("Error creating payment", e);
            meterRegistry.counter("payments.failed.total",
                    "service", "payment-service",
                    "environment", "local")
                    .increment();
            throw e;
        } finally {
            MDC.clear();
        }
    }

