1. **Ampersand Encoding**: The URL for the datasource uses `&amp;` which should be `&` in YAML files.
2. **Indentation**: Ensure consistent indentation for readability and to avoid parsing errors.
3. **Duplicate RabbitMQ Configuration**: The `rabbitmq` configuration is defined twice. Consolidate it into a single section.

Here's the corrected version:

```yaml::application.yml::C:/Users/baira/OneDrive/Documents/AI_Projects/payment-system/payment-service/src/main/resources/application.yml
# Payment Service Configuration
spring:
  application:
    name: payment-service

  # Database configuration
  datasource:
    url: jdbc:mysql://mysql:3306/payment_db?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC
    username: payment_user
    password: payment_pass
    driver-class-name: com.mysql.cj.jdbc.Driver
    hikari:
      maximum-pool-size: 10
      minimum-idle: 5
      connection-timeout: 30000
      idle-timeout: 600000
      max-lifetime: 1800000

  # JPA configuration
  jpa:
    hibernate:
      ddl-auto: update
    properties:
      hibernate:
        dialect: org.hibernate.dialect.MySQL8Dialect
        format_sql: true
        show_sql: false
        jdbc:
          batch_size: 25
        order_inserts: true
        order_updates: true
    open-in-view: false

  # RabbitMQ configuration
  rabbitmq:
    host: rabbitmq
    port: 5672
    username: guest
    password: guest
    virtual-host: /
    connection-timeout: 30000
    template:
      retry:
        enabled: true
        initial-interval: 1000
        max-attempts: 3
        max-interval: 10000
        multiplier: 2
    exchange:
      payment: payment.events
    queue:
      payment-events: payment-events-queue
      payment-events-dlq: payment-events-dlq
    routing-key:
      payment-created: payment.created

# Server configuration
server:
  port: 8080
  servlet:
    context-path: /api/v1
  compression:
    enabled: true
  error:
    include-message: always
    include-binding-errors: always

# Actuator configuration
management:
  endpoints:
    web:
      exposure:
        include: "*"
      base-path: /actuator
  endpoint:
    health:
      show-details: always
    prometheus:
      enabled: true
  metrics:
    export:
      prometheus:
        enabled: true
    tags:
      application: ${spring.application.name}
      environment: local
    distribution:
      percentiles-histogram:
        http.server.requests: true
      slo:
        http.server.requests: 50ms, 100ms, 200ms, 500ms, 1s, 2s

# Logging configuration
logging:
  level:
    root: INFO
    com.example.payment: DEBUG
    org.springframework.web: INFO
    org.springframework.amqp: INFO
    org.hibernate.SQL: DEBUG
    org.hibernate.type.descriptor.sql.BasicBinder: TRACE
  pattern:
    console: "%d{yyyy-MM-dd HH:mm:ss.SSS} [%thread] %-5level %logger{36} - traceId=%X{traceId:-N/A} spanId=%X{spanId:-N/A} paymentId=%X{paymentId:-N/A} - %msg%n"
    file: "{\"timestamp\":\"%d{yyyy-MM-dd HH:mm:ss.SSS}\",\"level\":\"%level\",\"thread\":\"%thread\",\"logger\":\"%logger{36}\",\"traceId\":\"%X{traceId:-N/A}\",\"spanId\":\"%X{spanId:-N/A}\",\"paymentId\":\"%X{paymentId:-N/A}\",\"message\":\"%msg\"}%n"
  file:
    name: /logs/payment-service.log
    max-size: 10MB
    max-history: 30
    total-size-cap: 1GB
```

### Key Changes:
- **Ampersand Correction**: Changed `&amp;` to `&` in the datasource URL.
- **Consolidated RabbitMQ Configuration**: Merged duplicate `rabbitmq` sections into one.
- **Indentation**: Ensured consistent indentation for better readability.






